import { sql } from "drizzle-orm";
import {
  check,
  foreignKey,
  index,
  integer,
  primaryKey,
  real,
  sqliteTable,
  text,
  uniqueIndex,
} from "drizzle-orm/sqlite-core";

// D1 stores dates as integer Unix epoch milliseconds. Opaque, globally unique
// text IDs are generated by the application so records can be created at the edge.
const timestamp = (name: string) => integer(name, { mode: "timestamp_ms" });
const currentTimestampMs = sql`(cast((julianday('now') - 2440587.5) * 86400000 as integer))`;
const createdAt = () =>
  timestamp("created_at").notNull().default(currentTimestampMs);
const updatedAt = () =>
  timestamp("updated_at").notNull().default(currentTimestampMs);

